Class<?> resolveSingle(Type t, Map<TypeVariable<?>, Type> map) {
        if (t instanceof Class<?>) {
            return (Class<?>) t;
        } else if (t instanceof ParameterizedType) {
            return (Class<?>) ((ParameterizedType) t).getRawType();
        } else if (t instanceof TypeVariable<?>) {
            Type resolved = map.get(t);
            if (resolved == null) {
                return null;
            }
            return resolveSingle(resolved, map);
        } else if (t instanceof WildcardType) {
            WildcardType wt = (WildcardType) t;
            Type[] upper = wt.getUpperBounds();
            if (upper.length > 0) {
                return resolveSingle(upper[0], map);
            }
            return Object.class;
        } else {
            return null;
        }
    }

