protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    // Ensure a valid range: if start is after end, swap them
    if (start > end) {
        long tmp = start;
        start = end;
        end = tmp;
    }
    if (start == end) {
        // No range to split
        return ranges;
    }
    // Split the interval into smaller segments of at most FETCH_DATA_DURATION
    long step = FETCH_DATA_DURATION;
    long current = start;
    while (current < end) {
        // Avoid overflow when adding step
        long next = Math.min(current + step, end);
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

