static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;
    // compute the start day of the interval
    long newDay = ((day - 1) / dayStep) * dayStep + 1;
    return year * 10000 + month * 100 + newDay;
}

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if(str==null || len<=0) return 0;
    int maxLen=str.length();
    int start=Math.max(0,index);
    int end=Math.min(maxLen,start+len);
    if(start>=end) return 0;
    int utf8Size=0;
    for(int i=start;i<end;){
        int cp=str.codePointAt(i);
        if(cp<=0x7F){
            utf8Size+=1;
        }else if(cp<=0x7FF){
            utf8Size+=2;
        }else if(cp<=0xFFFF){
            utf8Size+=3;
        }else{
            utf8Size+=4;
        }
        i+=Character.charCount(cp);
    }
    return utf8Size;
}

