private void putAbstractTypes(final int start, final int end) {
    try {
        if (currentFrame == null || stackMapTableEntries == null) {
            return;
        }
        final int len = currentFrame.length;
        if (start < 0 || end < start || end > len) {
            return;
        }
        for (int i = start; i < end; i++) {
            final org.objectweb.asm.Type type = currentFrame[i];
            if (type == null) {
                continue;
            }
            int tag;
            int extra = 0;
            switch (type.getSort()) {
                case org.objectweb.asm.Type.INT:
                    tag = 0; // ITEM_Integer
                    break;
                case org.objectweb.asm.Type.FLOAT:
                    tag = 1; // ITEM_Float
                    break;
                case org.objectweb.asm.Type.DOUBLE:
                    tag = 2; // ITEM_Double
                    break;
                case org.objectweb.asm.Type.LONG:
                    tag = 3; // ITEM_Long
                    break;
                case org.objectweb.asm.Type.OBJECT:
                    tag = 5; // ITEM_Object
                    extra = getConstantPoolIndex(type.getDescriptor());
                    break;
                case org.objectweb.asm.Type.ARRAY:
                    tag = 5; // ITEM_Object for array types
                    extra = getConstantPoolIndex(type.getDescriptor());
                    break;
                case org.objectweb.asm.Type.NULL:
                    tag = 4; // ITEM_UninitializedThis
                    break;
                default:
                    // Skip unsupported kinds
                    continue;
            }
            stackMapTableEntries.add(tag);
            if (tag == 5) {
                stackMapTableEntries.add((extra >> 8) & 0xFF);
                stackMapTableEntries.add(extra & 0xFF);
            }
        }
    } catch (Exception e) {
        // Defensive: log and swallow to avoid bleeding exceptions
        logger.warn("Failed to put abstract types into stackMapTableEntries", e);
    }
}

