public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        // The smallest prime number is 2
        return 2;
    }
    // Ensure the candidate starts at an odd number
    int candidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;
    // Continue searching upwards until a prime is found
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        // Avoid integer overflow; stop at Integer.MAX_VALUE - 2
        if (candidate > Integer.MAX_VALUE - 2) {
            throw new IllegalArgumentException("Cannot find a suitable prime");
        }
        candidate += 2; // Skip even numbers
    }
}

private static boolean isPrime(int n) {
    if (n == 2) {
        return true;
    }
    if (n <= 1 || n % 2 == 0) {
        return false;
    }
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 3; i <= sqrtN; i += 2) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

