public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; ) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= len) {
                // lone backslash at end, just append it
                sb.append('\\');
                i++;
            } else {
                char next = str.charAt(i + 1);
                switch (next) {
                    case 'b':
                        sb.append('\b');
                        i += 2;
                        break;
                    case 't':
                        sb.append('\t');
                        i += 2;
                        break;
                    case 'n':
                        sb.append('\n');
                        i += 2;
                        break;
                    case 'f':
                        sb.append('\f');
                        i += 2;
                        break;
                    case 'r':
                        sb.append('\r');
                        i += 2;
                        break;
                    case '"':
                        sb.append('"');
                        i += 2;
                        break;
                    case '\'':
                        sb.append('\'');
                        i += 2;
                        break;
                    case '\\':
                        sb.append('\\');
                        i += 2;
                        break;
                    case 'u':
                        // Unicode escape must have 4 hex digits
                        if (i + 5 >= len) {
                            throw new Exception("Incomplete unicode escape sequence at position " + i);
                        }
                        String hex = str.substring(i + 2, i + 6);
                        sb.append((char) Integer.parseInt(hex, 16));
                        i += 6;
                        break;
                    default:
                        // Unknown escape sequence
                        throw new Exception("Unknown escape sequence: \\" + next + " at position " + i);
                }
            }
        } else {
            sb.append(c);
            i++;
        }
    }
    return sb.toString();
}

