protected int removeUnusedNodes(){
    if (root == null) {
        return 0;
    }
    int removed = 0;
    Deque<Category> stack = new ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        Category current = stack.pop();
        List<Category> children = current.getChildren();
        if (children == null) {
            continue;
        }
        Iterator<Category> it = children.iterator();
        while (it.hasNext()) {
            Category child = it.next();
            if (!child.isActive()) {
                it.remove();
                removed++;
            } else {
                stack.push(child);
            }
        }
    }
    return removed;
}

