final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer){
    // locate the start of the constant pool entry
    int startOffset = this.constantPoolOffsets[constantPoolEntryIndex];
    if (startOffset < 0 || startOffset + 2 >= this.classFileBuffer.length)
        throw new IllegalArgumentException(
            "Invalid constant pool index or corrupted class file");
    // the first byte is the tag – it must be 1 for CONSTANT_Utf8
    int tag = this.classFileBuffer[startOffset] & 0xFF;
