        throw new IllegalArgumentException(
            "Entry at index " + constantPoolEntryIndex + " is not a CONSTANT_Utf8");
    // read the length (u2, big‑endian)
    int length = ((this.classFileBuffer[startOffset + 1] & 0xFF) << 8)
               | (this.classFileBuffer[startOffset + 2] & 0xFF);
    // make sure the supplied buffer is large enough
    if (charBuffer == null || charBuffer.length < length)
        throw new IllegalArgumentException(
            "Provided char buffer is too small for the UTF‑8 string");
    // decode the UTF‑8 bytes into a String and copy chars into the buffer
    String result = new String(
        this.classFileBuffer,
