protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    try {
        if (tour == null || tour.isEmpty() || graph == null) return null;

        // Build adjacency map: for each vertex, list of incident edges
        Map<V, List<E>> adjacency = new HashMap<>();
        for (E e : tour) {
            V source = graph.getEdgeSource(e);
            V target = graph.getEdgeTarget(e);
            adjacency.computeIfAbsent(source, k -> new ArrayList<>()).add(e);
            adjacency.computeIfAbsent(target, k -> new ArrayList<>()).add(e);
        }

        // Choose an arbitrary start vertex (from first edge)
        Iterator<E> it = tour.iterator();
        E firstEdge = it.next();
        V start = graph.getEdgeSource(firstEdge);
        V current = start;

        List<E> orderedEdges = new ArrayList<>();
        List<V> vertexList = new ArrayList<>();
        Set<E> remaining = new HashSet<>(tour);

        vertexList.add(start);

        E previousEdge = null;
        while (!remaining.isEmpty()) {
            E nextEdge = null;
            V nextVertex = null;
            for (E e : remaining) {
                V src = graph.getEdgeSource(e);
                V tgt = graph.getEdgeTarget(e);
                if (src.equals(current)) {
                    nextEdge = e;
                    nextVertex = tgt;
                    break;
                } else if (tgt.equals(current)) {
                    nextEdge = e;
                    nextVertex = src;
                    break;
                }
            }
            if (nextEdge == null) {
                // No connecting edge found; input not a valid tour
                return null;
            }
            orderedEdges.add(nextEdge);
            remaining.remove(nextEdge);
            vertexList.add(nextVertex);
            previousEdge = nextEdge;
            current = nextVertex;
        }

        // Calculate total weight
        double totalWeight = 0.0;
        for (E e : orderedEdges) {
            totalWeight += graph.getEdgeWeight(e);
        }

        // Return a new GraphPath implementation
        return new GraphPathImpl<>(graph, vertexList, orderedEdges, totalWeight);
    } catch (Exception e) {
        // Any exception results in null to indicate failure
        return null;
    }
}

int addConstantNameAndType(final String name, final String descriptor) {
    // Find or add the UTF-8 entries for name and descriptor
    int nameIndex = findUtf8(name);
    if (nameIndex == NOT_FOUND) {
        nameIndex = addUtf8(name);
    }
    int descriptorIndex = findUtf8(descriptor);
    if (descriptorIndex == NOT_FOUND) {
        descriptorIndex = addUtf8(descriptor);
    }

    // Search existing CONSTANT_NameAndType_info entries
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == NAME_TYPE) {
            int existingNameIndex = offsets[i];
            int existingDescriptorIndex = offsets[i + 1];
            if (existingNameIndex == nameIndex && existingDescriptorIndex == descriptorIndex) {
                return i;
            }
        }
    }

    // Add a new CONSTANT_NameAndType_info entry
    int newIndex = maxPoolSize++;
    types[newIndex] = NAME_TYPE;
    offsets[newIndex] = nameIndex;
    offsets[newIndex + 1] = descriptorIndex;
    return newIndex;
}

private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int length = input.length();
    for (int i = 0; i < length; i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 >= length) {
                // Backslash at end of string; skip it
                continue;
            }
            char next = input.charAt(i + 1);
            if (next == 'u') {
                // Attempt to parse a Unicode escape sequence \uXXXX
                if (i + 6 <= length) {
                    String hex = input.substring(i + 2, i + 6);
                    try {
                        int codePoint = Integer.parseInt(hex, 16);
                        result.append((char) codePoint);
                        i += 5; // Skip the processed sequence
                        continue;
                    } catch (NumberFormatException e) {
                        // Fall back to treating the sequence literally
                    }
                }
                // Invalid or incomplete \u escape; treat 'u' as literal
                result.append('u');
                i++; // Skip 'u'
            } else if (Character.isWhitespace(next)) {
                // Escape a whitespace character (ignored in identifier)
                i++; // Skip the whitespace as well
            } else {
                // Escape a normal character: just append the following character
                result.append(next);
                i++; // Skip the escaped character
            }
        } else {
            result.append(c);
        }
    }
    return result.toString();
}

public static String[] concatenateStringArrays(String[] array1,String[] array2){
    // Return null if both arrays are null
    if (array1 == null && array2 == null) {
        return null;
