    // If one of the arrays is null, return a shallow copy of the other array
    if (array1 == null) {
        return array2.clone();
    }
    if (array2 == null) {
        return array1.clone();
    }

    // Both arrays are non-null: concatenate them
    int length1 = array1.length;
    int length2 = array2.length;
    String[] result = new String[length1 + length2];
    try {
        System.arraycopy(array1, 0, result, 0, length1);
        System.arraycopy(array2, 0, result, length1, length2);
    } catch (ArrayStoreException | NullPointerException e) {
        // If a null array was encountered during copy or type mismatch, rethrow as a runtime exception
        throw new RuntimeException("Error while concatenating arrays", e);
    }
    return result;
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null) {
        throw new IllegalArgumentException("bucketsByLabel cannot be null");
    }
    if (labels == null) {
        throw new IllegalArgumentException("labels cannot be null");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel out of bounds");
    }
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return;
    }
    Set<Integer> target = bucketsByLabel.get(0);
    if (target == null) {
        target = new HashSet<>();
        bucketsByLabel.set(0, target);
    }
    for (Integer vertex : source) {
        if (vertex == null || vertex < 0 || vertex >= labels.size()) {
            continue;
        }
        labels.set(vertex, 0);
        target.add(vertex);
    }
    source.clear();
}

