private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    if (keys == null) {
        return lowerBounds;
    }
    for (K key : keys) {
        if (key == null) {
            lowerBounds.add(null);
            continue;
        }
        try {
            Integer current = (Integer) key;
            Integer maxLower = null;
            for (K other : keys) {
                if (other == null || other == key) {
                    continue;
                }
                try {
                    Integer oVal = (Integer) other;
                    if (oVal < current) {
                        if (maxLower == null || oVal > maxLower) {
                            maxLower = oVal;
                        }
                    }
                } catch (ClassCastException ignored) {
                }
            }
            lowerBounds.add(maxLower);
        } catch (ClassCastException e) {
            // key is not an Integer; record null as lower bound
            lowerBounds.add(null);
        }
    }
    return lowerBounds;
}

