    List<Integer> bounds = new ArrayList<>();
    if (keys == null){
        return bounds;
    }
    for (K key : keys) {
        try {
            bounds.add(key == null ? 0 : key.hashCode());
        } catch (Exception e) {
            bounds.add(0);
        }
    }
    return bounds;
}

