static String[] toNoNullStringArray(Object[] array) {
    if (array == null) {
        return new String[0];
    }
    int nullCount = 0;
    for (Object element : array) {
        if (element == null) {
            nullCount++;
        }
    }
    if (nullCount == 0) {
        try {
            return (String[]) array;
        } catch (ClassCastException e) {
            // fall through to create a new array if casting fails
        }
    }
    int resultSize = array.length - nullCount;
    String[] result = new String[resultSize];
    int index = 0;
    for (Object element : array) {
        if (element != null) {
            if (!(element instanceof String)) {
                throw new IllegalArgumentException(
                    "All non-null elements must be of type String");
            }
            result[index++] = (String) element;
        }
    }
    return result;
}

public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }
    int lastDot = filename.lastIndexOf('.');
    if (lastDot == -1) {
        return -1;
    }
    int lastSep = indexOfLastSeparator(filename);
    if (lastSep > lastDot) {
        return -1;
    }
    return lastDot;
}

public boolean isExpired(long timestamp,long expiredThreshold){
    if (expiredThreshold <= 0) {
        return false;
    }
    try {
        long now = System.currentTimeMillis();
        return now - timestamp > expiredThreshold;
    } catch (Exception e) {
        return true;
    }
}

Edge edgeToNext(){
    if (this._prevNode == null || this._nextNode == null) {
        return null;
    }
    Node fromNode = this._prevNode.isVirtual() ? this._prevNode.getRealNode() : this._prevNode;
    Node toNode = this._nextNode.isVirtual() ? this._nextNode.getRealNode() : this._nextNode;
    for (Edge e : this._edges) {
        if (e.getFrom() == fromNode && e.getTo() == toNode) {
            return e;
        }
    }
    return null;
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        return false;
    }
    int strLen = str.length();
    int subLen = substring.length();
    if (index < 0 || index > strLen) {
        return false;
    }
    if (subLen == 0) {
        return true; // empty substring always matches
    }
    if (index + subLen > strLen) {
        return false;
    }
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

