private void checkIfPackedField() throws IOException {
    // Ensure we have a descriptor for the current field
    if (fieldDescriptor == null) {
        return;
    }
    // Packed repeated fields are stored using the length‑delimited wire type (value 2)
    boolean packed = fieldDescriptor.isRepeated()
                     && fieldDescriptor.isPacked()
                     && wireType == 2;
    // Update the internal state to reflect that we are reading a packed field
    if (packed) {
        this.isReadingPackedField = true;
    } else {
        this.isReadingPackedField = false;
    }
}

