public static java.util.List<ThreadSnapshot> parseFromFileWithTimeRange(java.io.File file, java.util.List<ProfileAnalyzeTimeRange> timeRanges) throws java.io.IOException {
    if (file == null || !file.exists() || !file.isFile()) {
        throw new java.io.IOException("File is null, does not exist, or is not a regular file.");
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return java.util.Collections.emptyList();
    }
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    try (java.io.BufferedReader reader = new java.io.BufferedReader(new java.io.FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            ThreadSnapshot snapshot;
            try {
                snapshot = ThreadSnapshot.parse(line);
            } catch (Exception e) {
                // Skip lines that cannot be parsed into a ThreadSnapshot
                continue;
            }
            long timestamp = snapshot.getTimestamp();
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                long start = range.getStart();
                long end = range.getEnd();
                if (timestamp >= start && timestamp <= end) {
                    result.add(snapshot);
                    break;
                }
            }
        }
    } catch (java.io.IOException ioe) {
        throw ioe;
    } catch (Throwable t) {
        throw new java.io.IOException("Unexpected error while parsing thread snapshots", t);
    }
    return result;
}
